"""Self-contained research report; consumes independently validated J1 archives."""
import argparse,gzip,json,html,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'data/research/components/2026-10-15/joint-v5';OUT=ROOT.parent/'deliverables/FIE_J1_Joint_Forecast_Weeks_6_8_2026-10-15.html'
def load(n):return [json.loads(l) for l in gzip.open(BASE/'issuance'/(n+'.jsonl.gz'),'rt')]
def build():
 m=json.loads((BASE/'issuance/capture-manifest.json').read_text());v=json.loads((BASE/'independent-validation.json').read_text());assert v['status']=='PASS'
 rows=load('weekly-components');ledgers=load('team-ledgers');entities=json.loads((BASE/'entities.json').read_text())['entities'];em={e['canonical_player_id']:e for e in entities};keys=sorted({k for r in rows for k in {**r['means'],**r['event_probabilities']}})
 packed=[]
 for r in rows:
  val={**r['means'],**r['event_probabilities']};packed.append([r['canonical_player_id'],r['name'],r['position_model'],r['team'],r['week'],r['opponent'],r['available'],r['bye'],r['official_status'],r['injury_status'],[val.get(k,0) for k in keys]])
 scores=[];rules={}
 for r in map(json.loads,gzip.open(BASE/'issuance/weekly-league-scores.jsonl.gz','rt')):
  scores.append([r['canonical_player_id'],r['week'],r['league_id'],r['mean'],r['p10'],r['p50'],r['p90']]);pos=em[r['canonical_player_id']]['position_model'];rules[r['league_id']+'|'+pos]=[[key,x['component'],x['weight']] for key,x in r['contributions'].items()]
 b=json.loads((BASE/'observations/observation-bundle.json').read_text());profiles=[]
 for ref in b['responses']:
  if ref.get('role')=='profile':p=json.loads(gzip.decompress((ROOT/ref['path']).read_bytes()));profiles.append([str(p['league_id']),p['name']])
 payload={'keys':keys,'rows':packed,'scores':scores,'rules':rules,'profiles':profiles,'entities':{e['canonical_player_id']:{k:e[k] for k in ['identity_status','depth_order','snaps','official_status','provider_injury']} for e in entities},'ledgers':ledgers}
 e=lambda x:html.escape(str(x))
 def table(h,rs):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+e(x)+'</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(x)+'</td>' for x in r)+'</tr>' for r in rs)+'</tbody></table></div>'
 tnf=[r for r in rows if r['game_id']=='2026_06_SEA_DEN'];ls=[r for r in ledgers if r['game_id']=='2026_06_SEA_DEN'];summary=[]
 for team in ['SEA','DEN']:
  rr=[r for r in tnf if r['team']==team and r['position_model']!='DEF'];ss=lambda k:sum(r['means'].get(k,0) for r in rr);l=next(l for l in ls if l['team']==team)
  summary.append([team,*[f'{ss(k):.4f}' for k in ['passing_attempts','targets','passing_completions','receptions','passing_yards','receiving_yards','passing_touchdowns','receiving_touchdowns','rushing_attempts','rushing_yards']],f'{l["score"]:.4f}'])
 s='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>J1 joint component forecast</title><style>body{font:15px/1.5 system-ui;background:#f5f7fa;color:#172431;margin:0}main{max-width:1300px;margin:auto;padding:28px}h1,h2,h3{line-height:1.2}h2{margin-top:30px}.box{background:#e5f4eb;border-left:5px solid #23804a;padding:16px}.note{background:#fff1dc;padding:14px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px;background:white;margin:15px 0}th,td{padding:7px 9px;border-bottom:1px solid #dce4ec;text-align:left;vertical-align:top}th{background:#e7edf5}label{display:inline-block;margin:8px}select,input,button{padding:7px;font:inherit}details{padding:12px;background:white;margin:8px 0;border:1px solid #dbe2ea}summary{font-weight:650;cursor:pointer}.small{font-size:13px;color:#526170}code{overflow-wrap:anywhere}a{color:#185d9d}</style><main><h1>J1: shared team budgets, opponent context and availability</h1>'''
 s+=f'<div class="box"><b>Validated research forecast.</b> Weeks 6–8 · 23 leagues · {m["entities"]} entities · {m["games"]} NFL games · 1,024 shared scenarios per game. Independent archive checks: {v["checks"]:,}; failures: {v["error_count"]}. Weather is not used.</div><p>Issued {e(m["issued_at"])} (before first kickoff). Inputs: fresh 126-response capture at {e(b["observation_cutoff"])} plus separately archived official Thursday-game injury reports. Namespace: joint-v5. Earlier development runs remain preserved and rejected; original C4 B0/B1 forecasts are unchanged.</p>'
 s+='''<p>One matchup generates both teams’ player and defense credits. Attempts are allocated to the first available current QB role, carries and targets to supported current roles. Receiver catches, yards and touchdowns produce the same passer credits. Sacks, interceptions and lost offensive fumbles produce matching opposing defensive credits. Return counts have explicit opposing kick/punt capacity. TDs produce extra-point/two-point opportunities, and one scoring ledger supplies scoreboard and Sleeper points-allowed totals.</p>
<h2>Thursday game: Seattle at Denver</h2><p>Expected counts and yards are fractional means, not a prediction of a literal fractional game score. Source gross passing yards are used; sack losses belong in defensive net yards allowed.</p>'''
 s+=table(['Team','Pass ATT','Targets','Completions','Receptions','Pass yards','Rec yards','Pass TD','Rec TD','Carries','Rush yards','Score'],summary)
 s+='''<p>The attempt/target difference is an explicit non-targeted-throw ledger estimated from documented spikes/throwaway descriptions; it is not an unexplained reconciliation plug. Description-based identification can undercount non-targeted throws. QB backup production is not added to starter production. There is no invented in-game substitution or recovery probability.</p><p>Week 6 confirmed OUT: Seattle Drake Thomas, Chazz Surratt and Zach Charbonnet; Denver Talanoa Hufanga and Pat Surtain. Their new Week 6 forecasts are zero, with opportunities redistributed. Questionable/Doubtful statuses are retained as uncertainty without fabricated medical probabilities. OUT affects Week 6 only; Weeks 7–8 use declared static availability assumptions, not known recovery dates. Reserve/IR/PUP gates continue across the horizon.</p>
<h2>What changed, and what remains approximate</h2><ul><li>Team plays, passing share, completion/TD/INT/sack rates and yard efficiency combine an offense with its opposing allowed profile. Current 2026 Weeks 1–5 are shrunk with eight historical league-equivalent games; historical priors use 2021–2025. Rates use an equal logit blend; yard efficiency and volume use an equal mean blend. These fixed defaults are transparent, not optimized or validated for superiority.</li><li>Recent player weights remain source-bound B1 estimates; fresh depth/role, snap and availability observations determine allocation. Unsupported roles and tiny initial opportunity weights below 0.1 are excluded before normalization. Derived yards and rare probabilities are not independently rounded to zero.</li><li>Current opponent awareness is team-level. It does not model individual WR/CB assignments or apply an unvalidated numerical penalty for a particular opposing injury.</li><li>Yard distributions use historical empirical shapes scaled to matchup efficiency. Tackle/assist opportunities use opposing play counts with an approximate two-assist event rule. This is not a sequential drive simulator, and no home/rest/weather coefficients are applied.</li><li>Special-team forced/recovered fumbles, field-goal return yards and blocked-kick return yards have explicit zero prediction defaults until unit-attributed models exist. Zero prediction is not a claim that the source observed a zero. Field-goal yard totals use distance-bin midpoints.</li><li>Intervals are uncalibrated. Full provider semantic certification and prospective accuracy remain unproven. Arithmetic consistency is guaranteed for the tested relationships, not predictive accuracy or every possible football edge case.</li></ul>
<h2>Independent sense-check results</h2>'''
 s+=table(['Requirement','Result'],[['Pass completions / receiving receptions','Equal in every archived scenario and mean'],['Gross passing / credited receiving yards','Equal in every archived scenario and mean'],['Passing / receiving TD and two-point credits','Equal in every archived scenario and mean'],['Attempts / targets','Exact targets + explicit non-targeted attempts'],['Pass attempts + sacks + carries','Equal shared team play budget'],['Thrown / caught interceptions; sacks charged / credited','Same events across opposing teams'],['Lost offensive fumbles / opposing recoveries','Same regular-offense turnover ledger'],['IDP sacks / interceptions and D/ST totals','Reconciled'],['Confirmed unavailable rows and byes','Zero according to bound availability/calendar policy'],['FG makes/misses; XP makes/misses; TD conversion opportunities','Exact accounting; independent per-scenario FG sampling'],['Return attempts / return TDs','Within kick/punt/return/block opportunities'],['All league score contributions and quantiles','Replayed from the archived shared draws'],['Three-week sums and means','Replayed from those same weekly draw totals'],['Mean play/score plausibility','Passed broad prerelease bounds; no predictive accuracy claim']])
 s+='''<h2>Explore all teams, positions, components and leagues</h2><p>The complete raw forecasts and scored totals are embedded below; this file works offline. Component tables preserve exact archived expectations, including tiny values. A dash means that entity was not scored in the selected league/pool. Player P10/P50/P90 values must not be summed to obtain a team percentile.</p><label>Team <select id="team"></select></label><label>Week <select id="week"><option>6</option><option>7</option><option>8</option></select></label><label>Position <select id="pos"><option>ALL</option><option>QB</option><option>RB</option><option>WR</option><option>TE</option><option>K</option><option>DL</option><option>LB</option><option>DB</option><option>DEF</option></select></label><label>League <select id="league"></select></label><label>Player <input id="search" placeholder="Name"></label><div id="view"></div>
<h2>Thursday position and player component appendix</h2><p>This static appendix is available even if scripts are disabled. Every emitted component is included, with exact numerical expectations and event probabilities.</p>'''
 for team in ['SEA','DEN']:
  for pos in ['QB','RB','WR','TE','K','DL','LB','DB','DEF']:
   group=[r for r in tnf if r['team']==team and r['position_model']==pos];ks=sorted({k for r in group for k in {**r['means'],**r['event_probabilities']}})
   s+=f'<details><summary>{team} — {pos}: summed components ({len(group)} entities)</summary>'+table(['Component','Expected total / expected player-threshold count'],[[k,sum({**r['means'],**r['event_probabilities']}.get(k,0) for r in group)] for k in ks])+'</details>'
  for r in sorted([r for r in tnf if r['team']==team],key=lambda r:(r['position_model'],r['name'])):
   ent=em[r['canonical_player_id']];s+=f'<details><summary>{team} · {e(r["position_model"])} · {e(r["name"])}</summary><p>Available under current policy: {r["available"]}; official status: {e(r["official_status"])}; provider injury: {e(r["injury_status"])}; identity: {e(ent["identity_status"])}.</p>'+table(['Component','Exact expectation'],sorted({**r['means'],**r['event_probabilities']}.items()))+'</details>'
 s+='<h2>Sources and reproducibility</h2><p><a href="https://support.sleeper.com/en/articles/4126495-how-are-points-allowed-calculated">Sleeper points-allowed rules</a> · <a href="https://www.denverbroncos.com/team/injury-report/">Denver official injury report</a> · <a href="https://www.seahawks.com/team/injury-report/">Seattle official injury report</a>. All consumed source snapshots and every game’s full draw matrices are retained in the research archive.</p><p class="small">Forecast manifest SHA-256: '+e(v['manifest_sha256'])+'. Validation owner is independent of the issuer. Historical original pregame publication timing is unverified. Research only; no app, champion, ranking or transaction promotion. C5/C6 completion previously reported is not substantiated by the recovered workspace; this report concerns the newly implemented and verified J1 revision.</p></main>'
 s+='<script id="data" type="application/json">'+json.dumps(payload,separators=(',',':')).replace('</',r'<\/')+'</script>'
 s+='''<script>
const D=JSON.parse(document.getElementById('data').textContent),K=new Map(D.keys.map((k,i)=>[k,i])),scores=new Map(D.scores.map(r=>[r[0]+'|'+r[1]+'|'+r[2],r]));
const el=id=>document.getElementById(id),esc=x=>{const s=document.createElement('span');s.textContent=String(x??'');return s.innerHTML},n=x=>Number(x).toFixed(4),tbl=(h,rs)=>'<div class="scroll"><table><thead><tr>'+h.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rs.map(r=>'<tr>'+r.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
el('team').innerHTML=[...new Set(D.rows.map(r=>r[3]).filter(Boolean))].sort().map(x=>'<option>'+esc(x)+'</option>').join('');el('team').value='SEA';el('league').innerHTML=D.profiles.map(p=>'<option value="'+esc(p[0])+'">'+esc(p[1])+'</option>').join('');
function render(){let rs=D.rows.filter(r=>r[3]===el('team').value&&r[4]===Number(el('week').value)&&(el('pos').value==='ALL'||r[2]===el('pos').value)&&r[1].toLowerCase().includes(el('search').value.toLowerCase()));const lid=el('league').value;let out='<p>'+rs.length+' entities. Shared J1 raw stats; league-specific scored expectations.</p>';out+=tbl(['Position','Player','Available','Pass ATT','Carries','Targets','Catches','Rec yards','Fantasy mean','P10','P50','P90'],rs.map(r=>{const sc=scores.get(r[0]+'|'+r[4]+'|'+lid),v=k=>r[10][K.get(k)];return[r[2],r[1],r[6],v('passing_attempts'),v('rushing_attempts'),v('targets'),v('receptions'),v('receiving_yards'),...(sc?sc.slice(3).map(n):['—','—','—','—'])]}));
for(const r of rs){const fields=D.keys.filter(k=>k.startsWith('dst_')===(r[2]==='DEF')),rule=D.rules[lid+'|'+r[2]]||[],sc=scores.get(r[0]+'|'+r[4]+'|'+lid);out+='<details><summary>'+esc(r[1])+' — every component and score contribution</summary>'+tbl(['Component','Exact expectation'],fields.map(k=>[k,r[10][K.get(k)]]));if(sc)out+=tbl(['Scoring key','Component','Weight','Expected value','Expected points'],rule.map(q=>[q[0],q[1],q[2],r[10][K.get(q[1])],r[10][K.get(q[1])]*q[2]]));out+='<p class="small">Role inputs: '+esc(JSON.stringify(D.entities[r[0]]))+'</p></details>'}el('view').innerHTML=out;}
for(const id of ['team','week','pos','league'])el(id).addEventListener('change',render);el('search').addEventListener('input',render);render();
</script></html>'''
 OUT.parent.mkdir(parents=True,exist_ok=True);OUT.write_text(s);print('REPORT',OUT,OUT.stat().st_size);return OUT
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,default=OUT);args=p.parse_args();OUT=args.output;build()
